import React from 'react';

interface StatusItem {
  label: string;
  count: number;
  color: string;
}

interface MarketSegmentCardProps {
  title: string;
  subtitle: string;
  statusItems: StatusItem[];
}

const MarketSegmentCard: React.FC<MarketSegmentCardProps> = ({
  title,
  subtitle,
  statusItems
}) => {
  const getColorClasses = (color: string) => {
    switch (color) {
      case 'teal':
        return 'bg-teal-500';
      case 'blue':
        return 'bg-blue-500';
      case 'yellow':
        return 'bg-yellow-500';
      case 'green':
        return 'bg-green-500';
      case 'red':
        return 'bg-red-500';
      default:
        return 'bg-gray-500';
    }
  };

  const getTextColorClasses = (color: string) => {
    switch (color) {
      case 'teal':
        return 'text-teal-400';
      case 'blue':
        return 'text-blue-400';
      case 'yellow':
        return 'text-yellow-400';
      case 'green':
        return 'text-green-400';
      case 'red':
        return 'text-red-400';
      default:
        return 'text-gray-400';
    }
  };

  return (
    <div className="bg-slate-700 rounded-xl p-6 w-80">
      <div className="mb-6">
        <p className="text-slate-400 text-sm font-medium mb-1">{subtitle}</p>
        <h3 className="text-white text-lg font-semibold">{title}</h3>
      </div>

      <div className="space-y-4">
        {statusItems.map((item, index) => (
          <div key={index} className="flex items-center justify-between">
            <div className="flex items-center space-x-3">
              <div className={`w-1 h-6 rounded-full ${getColorClasses(item.color)}`} />
              <span className="text-slate-300 text-sm font-medium">{item.label}</span>
            </div>
            <span className={`text-2xl font-bold ${getTextColorClasses(item.color)}`}>
              {item.count}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
};

export default MarketSegmentCard;

import React, { useState } from 'react';
import { MoreVertical, Trash2 } from 'lucide-react';

interface ClientCardProps {
  clientName: string;
  clientId: string;
  onDelete?: () => void;
}

const ClientCard: React.FC<ClientCardProps> = ({ clientName, clientId, onDelete }) => {
  const [showMenu, setShowMenu] = useState(false);

  const handleMenuToggle = () => {
    setShowMenu(!showMenu);
  };

  const handleDelete = () => {
    if (onDelete) {
      onDelete();
    }
    setShowMenu(false);
  };

  return (
    <div className="relative bg-white rounded-lg border border-gray-200 p-4 shadow-sm">
      {/* Header with client name and menu */}
      <div className="flex items-start justify-between mb-2">
        <h3 className="text-lg font-semibold text-gray-900 leading-6">
          {clientName}
        </h3>

        <div className="relative">
          <button
            onClick={handleMenuToggle}
            className="p-1 hover:bg-gray-100 rounded-md transition-colors"
            aria-label="Client options menu"
            aria-expanded={showMenu}
            aria-haspopup="true"
          >
            <MoreVertical className="w-5 h-5 text-gray-500" />
          </button>

          {/* Dropdown menu */}
          {showMenu && (
            <div className="absolute right-0 top-8 bg-white border border-gray-200 rounded-md shadow-lg z-10 min-w-[120px]">
              <button
                onClick={handleDelete}
                className="flex items-center w-full px-3 py-2 text-sm text-red-600 hover:bg-red-50 transition-colors"
                role="menuitem"
                aria-label={`Delete client ${clientName}`}
              >
                <Trash2 className="w-4 h-4 mr-2" />
                Delete
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Client ID */}
      <div className="flex items-center">
        <span className="text-sm text-gray-500 mr-2">Client ID</span>
        <span className="text-sm font-medium text-gray-700">{clientId}</span>
      </div>

      {/* Click outside to close menu */}
      {showMenu && (
        <div 
          className="fixed inset-0 z-0" 
          onClick={() => setShowMenu(false)}
          aria-hidden="true"
        />
      )}
    </div>
  );
};

export default ClientCard;

