};

const Commissions: React.FC = () => {
  return (
    <div className="p-4 space-y-4">
      <CommissionCard
        title="October total earned"
        amount="$5,038.24"
        percentage="+8%"
        trend="up"
      />
      <CommissionCard
        title="October total earned"
        amount="$5,038.24"
        percentage="+12%"
        trend="up"
      />
    </div>
  );
};

export default Commissions;
